#include <iostream>
using namespace std;
int findSecondLargest(int arr[], int n)
{
    // Find the maximum element in the array
    int max = INT_MIN;
    for (int i = 0; i < n; i++)
        if (arr[i] > max)
            max = arr[i];

    // Scan through the remaining elements to find the second largest element
    int secondMax = -1;
    for (int i = 0; i < n; i++)
    {
        if (arr[i] != max && (secondMax == -1 || arr[i] > secondMax))
